export interface ReleaseVersion {
  major: number
  minor: number
  patch: number
  rc: number | null
}

/** Only versions generated by Spindle's tag-push release workflow are installable. */
export function parseReleaseVersion(version: string): ReleaseVersion | null {
  const match = /^(?:v)?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-rc\.(0|[1-9]\d*))?$/.exec(version)
  if (!match) return null
  const parts = match.slice(1, 4).map(Number)
  const rc = match[4] === undefined ? null : Number(match[4])
  if (parts.some((n) => !Number.isSafeInteger(n)) || (rc !== null && !Number.isSafeInteger(rc))) return null
  return { major: parts[0], minor: parts[1], patch: parts[2], rc }
}

export function isPrereleaseVersion(version: string): boolean {
  const parsed = parseReleaseVersion(version)
  return parsed !== null && parsed.rc !== null
}

export function isNewerRelease(current: string, candidate: string): boolean {
  const a = parseReleaseVersion(current)
  const b = parseReleaseVersion(candidate)
  if (!a || !b) return false
  for (const key of ['major', 'minor', 'patch'] as const) {
    if (a[key] !== b[key]) return b[key] > a[key]
  }
  if (a.rc === b.rc) return false
  if (b.rc === null) return a.rc !== null // stable is newer than its RCs
  if (a.rc === null) return false // an RC cannot downgrade a stable install
  return b.rc > a.rc
}

/** Stable installs default to stable, RC installs default to RC + stable.
 * Explicit preferences may override the channel, never semver ordering.
 */
export function isEligibleUpdate(
  current: string, candidate: string, includePrereleases = isPrereleaseVersion(current)
): boolean {
  if (!isNewerRelease(current, candidate)) return false
  return includePrereleases || !isPrereleaseVersion(candidate)
}

export type UpdatePhase =
  | 'disabled' | 'idle' | 'checking' | 'up-to-date'
  | 'available' | 'downloading' | 'ready' | 'installing' | 'error'

export type UpdateOperation = 'check' | 'download' | 'install'
export type UpdateInstallType = 'deb' | 'appimage' | 'nsis' | 'unknown'

export interface UpdateStatus {
  phase: UpdatePhase
  currentVersion: string
  availableVersion: string | null
  percent: number | null
  message: UpdateErrorCode | null
  installType: UpdateInstallType
  failureStage: UpdateOperation | null
}

/** Don't leak token-bearing updater URLs or raw HTTP headers to the renderer. */
export type UpdateErrorCode = 'auth' | 'network' | 'verification' | 'generic'
  | 'install-failed' | 'not-installed' | 'wrong-launcher'

/** Report only recognized failure categories, never raw token-bearing HTTP errors. */
export function updateErrorMessage(error: unknown): UpdateErrorCode {
  const raw = error instanceof Error ? error.message : String(error)
  if (/401|403|404|not.found|unauthori[sz]ed|access.denied|authentication/i.test(raw)) return 'auth'
  if (/ENOTFOUND|ETIMEDOUT|ECONN|network|socket|timeout/i.test(raw)) return 'network'
  if (/signature|sha512|checksum|hash mismatch/i.test(raw)) return 'verification'
  return 'generic'
}
